mapper.select:
SELECT id, category_id, parent_id, depth, tag_code, tag_name, sort, status,
       create_time, update_time, lock_version
FROM blade_tag
WHERE tenant_id = #{tenantId} AND is_deleted = 0
AND category_id = #{categoryId}
AND parent_id = #{parentId}
AND tag_name LIKE CONCAT('%', #{name}, '%')
AND tag_code LIKE CONCAT('%', #{code}, '%')
AND status = #{status}
ORDER BY sort ASC, create_time ASC, id ASC

SELECT * FROM blade_tag
WHERE tenant_id = #{tenantId} AND category_id = #{categoryId} AND tag_code = #{code}
LIMIT 1

SELECT COUNT(1) FROM blade_tag
WHERE tenant_id = #{tenantId} AND category_id = #{categoryId}
  AND parent_id = #{parentId} AND is_deleted = 0
